/**
 * TikTok Shop Inventory Search → canonical InventoryLevel.
 *
 * Inventory Search 202309 (POST /product/202309/inventory/search,
 * https://partner.tiktokshop.com/docv2/page/650a9191c16ffe02b8eec161) answers
 * `data.inventory[]`, one entry per requested product:
 *
 *   ^inventory            "Inventory information for the requested products or SKUs."
 *   ^^product_id          "The ID of the requested product."
 *   ^^skus                "The list of requested SKUs."
 *   ^^^id                 "The SKU ID generated by TikTok Shop."
 *   ^^^warehouse_inventory "SKU warehouse inventory information."
 *   ^^^^warehouse_id      "The ID of the warehouse where the SKU is stored."
 *   ^^^^available_quantity "The total number of units available for ordering in this warehouse."
 *   ^^^^committed_quantity "The total number of units reserved by existing customer
 *                          orders in this warehouse (and therefore not available for ordering)."
 *
 * One InventoryLevel per SKU per warehouse, id `${skuId}:${warehouseId}`. The
 * SKU id is the variant id `transformVariants` emits, and the warehouse id is
 * the location id `transformLocation` emits (Get Warehouse List).
 */

import type { InventoryLevel } from '../../../schema/inventory'

// ── Raw shapes (documented fields only) ─────────────────────────────────────

export interface RawTikTokWarehouseInventory {
  warehouse_id?: string
  available_quantity?: number
  committed_quantity?: number
}

export interface RawTikTokInventorySku {
  id?: string
  seller_sku?: string
  total_available_quantity?: number
  total_committed_quantity?: number
  warehouse_inventory?: RawTikTokWarehouseInventory[]
  [key: string]: unknown
}

export interface RawTikTokProductInventory {
  product_id?: string
  skus?: RawTikTokInventorySku[]
}

// ── Transform ────────────────────────────────────────────────────────────────

function level(
  productId: string | undefined,
  sku: RawTikTokInventorySku,
  skuId: string,
  wh: RawTikTokWarehouseInventory,
): InventoryLevel {
  if (!wh.warehouse_id) {
    throw new Error(
      `TikTok Shop inventory: SKU '${skuId}' has a warehouse entry with no warehouse_id`,
    )
  }
  if (typeof wh.available_quantity !== 'number') {
    throw new Error(
      `TikTok Shop inventory: SKU '${skuId}' in warehouse '${wh.warehouse_id}' has no available_quantity`,
    )
  }
  const committed = typeof wh.committed_quantity === 'number' ? wh.committed_quantity : undefined
  return {
    id: `${skuId}:${wh.warehouse_id}`,
    variantId: skuId,
    locationId: wh.warehouse_id,
    available: wh.available_quantity,
    committed,
    onHand: committed !== undefined ? wh.available_quantity + committed : undefined,
    metadata: {
      productId,
      sellerSku: sku.seller_sku,
      warehouseInventory: wh,
    },
  }
}

/** Every SKU × warehouse row of one Inventory Search `inventory[]` entry. */
export function transformInventoryLevels(raw: RawTikTokProductInventory): InventoryLevel[] {
  const rows: InventoryLevel[] = []
  for (const sku of raw.skus ?? []) {
    if (!sku.id) {
      throw new Error(`TikTok Shop inventory: product '${raw.product_id}' has a SKU with no id`)
    }
    for (const wh of sku.warehouse_inventory ?? []) {
      rows.push(level(raw.product_id, sku, sku.id, wh))
    }
  }
  return rows
}
